import 'dart:io';
import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
class Cam extends StatefulWidget{const Cam({super.key});@override State<Cam> createState()=>_C();}
class _C extends State<Cam>{File? f;
  Future<void> shoot()async{final r=await ImagePicker().pickImage(source:ImageSource.camera,imageQuality:80);if(r!=null)setState(()=>f=File(r.path));}
  @override Widget build(BuildContext c)=>Scaffold(body:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[ElevatedButton(onPressed:shoot,child:const Text('Shoot')),if(f!=null)Image.file(f!,width:240)])));}
